package vn.codegym.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import vn.codegym.repository.ProductRepository;import java.io.*;@WebServlet("/products")public class ProductServlet extends HttpServlet{private final ProductRepository repo=new ProductRepository();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String action=r.getParameter("action");if("delete".equals(action)){repo.delete(Integer.parseInt(r.getParameter("id")));s.sendRedirect("products");return;}r.setAttribute("products",repo.findAll());r.getRequestDispatcher("/products.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{r.setCharacterEncoding("UTF-8");String action=r.getParameter("action"),name=r.getParameter("name");double price=Double.parseDouble(r.getParameter("price"));if("update".equals(action))repo.update(Integer.parseInt(r.getParameter("id")),name,price);else repo.add(name,price);s.sendRedirect("products");}}
